# Helper function to record validation
validate <- function(test_name, condition, expected, actual, severity = "ERROR") {
  status <- if (condition) "PASS" else severity

  validation_results[[test_name]] <<- list(
    status = status,
    expected = expected,
    actual = actual
  )

  if (!condition) {
    issues_found[[length(issues_found) + 1]] <<- list(
      test = test_name,
      severity = severity,
      expected = expected,
      actual = actual
    )
  }

  return(condition)
}

