# Test primary key uniqueness for key tables
test_pk <- function(db_name, table_name, pk_cols) {
  tables <- dm_get_tables(get(db_name))

  if (table_name %in% names(tables)) {
    tbl <- tables[[table_name]]

    # Check columns exist
    missing_cols <- setdiff(pk_cols, names(tbl))
    if (length(missing_cols) > 0) {
      cat("  ⚠️  ", db_name, "$", table_name, ": Missing PK columns: ",
          paste(missing_cols, collapse = ", "), "\n", sep = "")
      return(FALSE)
    }

    # Check uniqueness
    # Handle NA values in PKs
    has_na <- tbl %>%
      select(all_of(pk_cols)) %>%
      summarise(across(everything(), ~sum(is.na(.)))) %>%
      summarise(total = sum(c_across(everything()))) %>%
      pull(total)

    if (has_na > 0) {
      validate(paste0(db_name, "$", table_name, ": PK has no NAs"),
               FALSE,
               "0 NAs",
               paste(has_na, "NAs in PK columns"),
               "WARNING")
    }

    # Count distinct vs total
    distinct_count <- tbl %>%
      distinct(across(all_of(pk_cols))) %>%
      nrow()

    total_count <- nrow(tbl)

    validate(paste0(db_name, "$", table_name, ": PK uniqueness"),
             distinct_count == total_count,
             paste(total_count, "rows =", total_count, "unique"),
             paste(total_count, "rows =", distinct_count, "unique"))

    if (distinct_count != total_count) {
      duplicates <- total_count - distinct_count
      cat("  ❌ ", duplicates, " duplicate PK combinations found\n", sep = "")
    } else {
      cat("  ✓ ", db_name, "$", table_name, ": PK unique (",
          format(total_count, big.mark = ","), " rows)\n", sep = "")
    }

    return(distinct_count == total_count)
  } else {
    cat("  ⚠️  Table not found: ", db_name, "$", table_name, "\n", sep = "")
    return(FALSE)
  }
}

# Test key primary keys
test_pk("ffa_db", "ffa_player_ids", "id")
